class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        int N = 1 << n;
        vector<int> dp(N, INT_MAX);
        dp[0] = 0;

        int m = stickers.size();
        vector<vector<int>> cnt(m, vector<int>(26, 0));
        for (int i = 0; i < m; i++) {
            for (char c : stickers[i]) cnt[i][c - 'a']++;
        }

        for (int mask = 0; mask < N; mask++) {
            if (dp[mask] == INT_MAX) continue;
            for (int i = 0; i < m; i++) {
                vector<int> avail = cnt[i];
                int newMask = mask;
                for (int j = 0; j < n; j++) {
                    if ((mask >> j) & 1) continue;
                    int idx = target[j] - 'a';
                    if (avail[idx] > 0) {
                        avail[idx]--;
                        newMask |= (1 << j);
                    }
                }
                if (newMask != mask && dp[mask] + 1 < dp[newMask]) {
                    dp[newMask] = dp[mask] + 1;
                }
            }
        }
        return dp[N - 1] == INT_MAX ? -1 : dp[N - 1];
    }
};
